CREATE COLUMN TABLE "TEST_AP"."OCFL" ("Code" INTEGER CS_INT NOT NULL , "DateID" LONGDATE CS_LONGDATE, "Dscription" NVARCHAR(50), "Project" NVARCHAR(20), "Credit" DECIMAL(21,6) CS_FIXED, "CredCur" NVARCHAR(3), "Debit" DECIMAL(21,6) CS_FIXED, "DebCur" NVARCHAR(3), "SecLevel" SMALLINT CS_INT DEFAULT 1, "UserId" SMALLINT CS_INT NOT NULL , "Frequency" NVARCHAR(1) DEFAULT 'O', "Remind" SMALLINT CS_INT DEFAULT -1, "EndDate" LONGDATE CS_LONGDATE, "OcrCode" NVARCHAR(8), "OcrCode2" NVARCHAR(8), "OcrCode3" NVARCHAR(8), "OcrCode4" NVARCHAR(8), "OcrCode5" NVARCHAR(8), PRIMARY KEY ("Code", "UserId")) UNLOAD PRIORITY 5  AUTO MERGE 